  "四、 Python 原生实现：Fletcher-16 生成与校验逻辑": "IV. Native Python Implementation: Fletcher-16 Generation and Verification Logic",
  "可以在本地直接运行验证任何一条 LSA 的 Checksum 生成与自验：": "You can run this locally to verify the Checksum generation and self-verification of any LSA:",
  "def fletcher16_lsa_checksum(lsa_bytes: bytearray) -> int:\n    \"\"\"\n    输入: 完整的 LSA bytearray (包含 20 字节头部)\n    输出: 计算出的 16-bit 校验和 (X, Y)\n    \"\"\"": "def fletcher16_lsa_checksum(lsa_bytes: bytearray) -> int:\n    \"\"\"\n    Input: Complete LSA bytearray (including 20-byte header)\n    Output: Calculated 16-bit checksum (X, Y)\n    \"\"\"",
  "# 1. 复制数据，避开原始对象修改": "# 1. Copy data to avoid modifying the original object",
  "# 2. RFC 规定：计算前必须将 LS Age (前 2 字节) 和 Checksum (第 16, 17 字节，0-based) 置零": "# 2. RFC requirement: LS Age (first 2 bytes) and Checksum (16th, 17th bytes, 0-based) must be set to zero before calculation",
  "# 3. 执行 Fletcher 迭代累加": "# 3. Perform Fletcher iterative accumulation",
  "# 4. 求解填入第 16, 17 字节的 X, Y 值": "# 4. Solve for X, Y values to be filled into the 16th and 17th bytes",
  "# N = 总字节数, K = Checksum 所在偏移位置 (1-based, 对应第 17 字节)": "# N = total bytes, K = Checksum offset position (1-based, corresponding to the 17th byte)",
  "# 5. 组合成 16-bit 大端整数 (X 在前，Y 在后)": "# 5. Combine into a 16-bit big-endian integer (X first, Y second)",
  "checksum = (x << 8) | y\n    return checksum\n\ndef verify_lsa_checksum(lsa_bytes: bytes) -> bool:\n    \"\"\"\n    接收方极速验证：包含 Checksum 的全量数据跑一次 Fletcher，若 c0=0 且 c1=0 则校验通过\n    \"\"\"\n    data = bytearray(lsa_bytes)\n    data[0] = 0\n    data[1] = 0  # 忽略 LS Age\n\n    c0 = 0\n    c1 = 0\n    for byte in data:\n        c0 = (c0 + byte) % 255\n        c1 = (c1 + c0) % 255\n\n    return (c0 == 0) and (c1 == 0)": "checksum = (x << 8) | y\n    return checksum\n\ndef verify_lsa_checksum(lsa_bytes: bytes) -> bool:\n    \"\"\"\n    Receiver rapid verification: Run Fletcher on the full data including the Checksum; if c0=0 and c1=0, verification passes\n    \"\"\"\n    data = bytearray(lsa_bytes)\n    data[0] = 0\n    data[1] = 0  # Ignore LS Age\n\n    c0 = 0\n    c1 = 0\n    for byte in data:\n        c0 = (c0 + byte) % 255\n        c1 = (c1 + c0) % 255\n\n    return (c0 == 0) and (c1 == 0)",
